<#
.Synopsis
Checks that the IP Address Space to be allocated for this Community is available.
.Description
Checks that the IP Address Space to be allocated for this Community is available.
.Example
$communityId = '/subscriptions/<subscriptionId>/resourceGroups/mission-rg/providers/Microsoft.Mission/communities/contoso-community'
Test-AzMissionCommunityAddressSpaceAvailability -CommunityName 'contoso-community' -ResourceGroupName 'mission-rg' -CommunityResourceId $communityId -EnclaveVirtualNetworkName 'enclave-vnet' -EnclaveVirtualNetworkCustomCidrRange '10.0.2.0/24' -EnclaveVirtualNetworkSize 'small'

.Inputs
Microsoft.Azure.PowerShell.Cmdlets.Mission.Models.ICheckAddressSpaceAvailabilityRequest
.Inputs
Microsoft.Azure.PowerShell.Cmdlets.Mission.Models.IMissionIdentity
.Outputs
Microsoft.Azure.PowerShell.Cmdlets.Mission.Models.ICheckAddressSpaceAvailabilityResponse
.Notes
COMPLEX PARAMETER PROPERTIES

To create the parameters described below, construct a hash table containing the appropriate properties. For information on hash tables, run Get-Help about_Hash_Tables.

CHECKADDRESSSPACEAVAILABILITYREQUEST <ICheckAddressSpaceAvailabilityRequest>: Request to the action call to check address space availability.
  CommunityResourceId <String>: Resource Id of the Community
  [EnclaveVirtualNetworkAllowSubnetCommunication <Boolean?>]: Allow Subnet Communication.
  [EnclaveVirtualNetworkCustomCidrRange <String>]: Custom CIDR Range.
  [EnclaveVirtualNetworkName <String>]: Network Name.
  [EnclaveVirtualNetworkSize <String>]: Network Size.
  [EnclaveVirtualNetworkSubnetConfiguration <List<ISubnetConfiguration>>]: Subnet Configurations.
    NetworkPrefixSize <Int32>: Network prefix size.
    SubnetName <String>: Subnet name.
    [SubnetDelegation <String>]: Subnet delegation.

ENCLAVEVIRTUALNETWORKSUBNETCONFIGURATION <ISubnetConfiguration[]>: Subnet Configurations.
  NetworkPrefixSize <Int32>: Network prefix size.
  SubnetName <String>: Subnet name.
  [SubnetDelegation <String>]: Subnet delegation.

INPUTOBJECT <IMissionIdentity>: Identity Parameter
  [ApprovalName <String>]: The name of the approvals resource.
  [CommunityEndpointName <String>]: The name of the Community Endpoint Resource
  [CommunityName <String>]: The name of the communityResource Resource
  [DedicatedHubName <String>]: The name of the Dedicated Hub Resource
  [EnclaveConnectionName <String>]: The name of the Enclave Connection Resource
  [EnclaveEndpointName <String>]: The name of the Enclave Endpoint Resource
  [Id <String>]: Resource identity path
  [ResourceGroupName <String>]: The name of the resource group. The name is case insensitive.
  [ResourceUri <String>]: The fully qualified Azure Resource manager identifier of the resource.
  [SubscriptionId <String>]: The ID of the target subscription. The value must be an UUID.
  [TransitHubName <String>]: The name of the TransitHub Resource
